    "hwdef-bl.dat": "# hw definition file for processing by chibios_hwdef.py\n# for the TAIPHOON flight controller\n\n# New board 20250818\n\n# MCU class and specific type\nMCU STM32H7xx STM32H743xx\n\n# crystal frequency\nOSCILLATOR_HZ 8000000\n\n# board ID. See Tools/AP_Bootloader/board_types.txt\nAPJ_BOARD_ID AP_HW_Morakot\n\n# ChibiOS system timer\n# STM32_ST_USE_TIMER 2\n\n# bootloader is installed at zero offset\nFLASH_RESERVE_START_KB 0\n\n# flash size\nFLASH_SIZE_KB 2048\n\n# the location where the bootloader will put the firmware\nFLASH_BOOTLOADER_LOAD_KB 128\n\n# USB setup\n# USB_VENDOR 0xABCD # ONLY FOR USE BY HEX! NOBODY ELSE\n# USB_PRODUCT 0x1058\nUSB_STRING_MANUFACTURER \"Taiphoon\"\n\n# baudrate to run bootloader at on uarts\ndefine BOOTLOADER_BAUDRATE 115200\n\n# pins for SWD debugging\nPA13 JTMS-SWDIO SWD\nPA14 JTCK-SWCLK SWD\n\n# order of UARTs (and USB)\nSERIAL_ORDER OTG1 USART1 USART2 USART3 UART5 USART6 UART7\n\n# USB\nPA11 OTG_FS_DM OTG1\nPA12 OTG_FS_DP OTG1\nPA9  VBUS      INPUT    OPENDRAIN\n\n# USART1\nPB14  USART1_TX USART1\nPB15  USART1_RX USART1\n\n# USART2\nPD5  USART2_TX USART2\nPD6  USART2_RX USART2\n\n# USART3\nPD8  USART3_TX USART3\nPD9  USART3_RX USART3\n\n# UART5 \nPB6  UART5_TX UART5\nPB5  UART5_RX UART5\n\n# USART6\nPC6  USART6_TX USART6\nPC7  USART6_RX USART6\n\n# UART7\nPE8  UART7_TX UART7\nPE7  UART7_RX UART7\n\n# UART8\nPE1  UART8_TX UART8\nPE0  UART8_RX UART8\n\n# I2C1 - external MAG/BARO\n# PB8 I2C1_SCL I2C1\n# PB9 I2C1_SDA I2C1\n# I2C_ORDER I2C1\n# define HAL_I2C_INTERNAL_MASK 0\n\n# ADC for Power\nPC0 BATT_VOLTAGE_SENS ADC1 SCALE(1)\nPC2 BATT_CURRENT_SENS ADC1 SCALE(1)\n\n# BUZZER and LED_STRIP\nPD15 BUZZER OUTPUT\n\n# LED\n# LED1 HIGH, LED2 LOW, LED3 HIGH = 紅色\n# LED1 LOW, LED2 HIGH, LED3 HIGH = 綠色\n# LED1 表示紅色, LED2表示紅色, LED3表示藍色\nPD12 LED_RED       OUTPUT OPENDRAIN GPIO(89) LOW \nPD13 LED_BLUE      OUTPUT OPENDRAIN GPIO(90) HIGH\nPD10 LED_GREEN     OUTPUT OPENDRAIN GPIO(91) LOW\n\n# 控制WS2812B LEDs\ndefine AP_NOTIFY_GPIO_LED_RGB_RED_PIN 89\ndefine AP_NOTIFY_GPIO_LED_RGB_BLUE_PIN 91\ndefine AP_NOTIFY_GPIO_LED_RGB_GREEN_PIN 90\ndefine AP_NOTIFY_GPIO_LED_RGB_ENABLED 1\n\n# Battery monitor\ndefine HAL_BATTMON_INA2XX_BUS 1\ndefine HAL_BATTMON_INA2XX_ADDR 0\ndefine HAL_BATT_MONITOR_DEFAULT 21\n\n# DFU bootloader support\nENABLE_DFU_BOOT 1\n# define AP_BOOTLOADER_FLASHING_ENABLED 1\n\n\n\n",
    "hwdef.dat": "# hw definition file for processing by chibios_hwdef.py\n# for the AeroCore hardware\n\n# New board 20250818\n\n# MCU class and specific type\nMCU STM32H7xx STM32H743xx\n\n# board ID for firmware load\nAPJ_BOARD_ID AP_HW_Morakot\n\n# crystal frequency\nOSCILLATOR_HZ 8000000\n\n# ChibiOS system timer\nSTM32_ST_USE_TIMER 4\ndefine CH_CFG_ST_RESOLUTION 16\n\n# flash size\nFLASH_SIZE_KB 2048\nFLASH_RESERVE_START_KB 128\n\n# USB setup\n# USB_VENDOR 0x2DAE # ONLY FOR USE BY HEX! NOBODY ELSE\n# USB_PRODUCT 0x1058\nUSB_STRING_MANUFACTURER \"Taiphoon\"\n\ndefine HAL_STORAGE_SIZE 32768\nSTORAGE_FLASH_PAGE 14\n\n# default to all pins low to avoid ESD issues\nDEFAULTGPIO OUTPUT LOW PULLDOWN\n\n# order of UARTs (and USB)\nSERIAL_ORDER OTG1 USART1 USART2 USART3 UART5 USART6 UART7 UART8 # Original\n\n# USB\nPA11 OTG_FS_DM OTG1\nPA12 OTG_FS_DP OTG1\nPA9  VBUS      INPUT    OPENDRAIN\n\n# USART1 (DJI/VTX)\nPB14  USART1_TX USART1\nPB15  USART1_RX USART1\ndefine DEFAULT_SERIAL1_BAUD 115\ndefine DEFAULT_SERIAL1_PROTOCOL SerialProtocol_MSP_DisplayPort \n\n\n# USART2\nPD5  USART2_TX USART2\nPD6  USART2_RX USART2\ndefine DEFAULT_SERIAL2_PROTOCOL SerialProtocol_None \n\n# USART3 (S.BUS)\nPD8  USART3_TX USART3 # Original\nPD9  USART3_RX USART3 # Original\ndefine DEFAULT_SERIAL3_PROTOCOL SerialProtocol_Sbus1\n\n# UART5 (GPS)\nPB6  UART5_TX UART5\nPB5  UART5_RX UART5\ndefine DEFAULT_SERIAL4_BAUD 230\ndefine DEFAULT_SERIAL4_PROTOCOL SerialProtocol_GPS\n\n# USART6 (ESC1)\nPC6  USART6_TX USART6\nPC7  USART6_RX USART6\ndefine DEFAULT_SERIAL5_BAUD 115\ndefine DEFAULT_SERIAL5_PROTOCOL SerialProtocol_ESCTelemetry \n\n# UART7 (UART)\nPE8  UART7_TX UART7\nPE7  UART7_RX UART7\nPE9  UART7_RTS UART7\nPE10 UART7_CTS UART7\ndefine DEFAULT_SERIAL6_BAUD 115\ndefine DEFAULT_SERIAL6_PROTOCOL SerialProtocol_MAVLink\n\n# UART8 (RC)\nPE1  UART8_TX UART8\nPE0  UART8_RX UART8\ndefine DEFAULT_SERIAL7_BAUD 57\ndefine DEFAULT_SERIAL7_PROTOCOL SerialProtocol_RCIN\n\n# ADC for Power\nPC0 BATT_VOLTAGE_SENS ADC1 SCALE(1)\nPC2 BATT_CURRENT_SENS ADC1 SCALE(1)\n\n# SDMMC\nPC12   SDMMC1_CK    SDMMC1\nPD2    SDMMC1_CMD   SDMMC1\nPC8    SDMMC1_D0    SDMMC1\nPC9    SDMMC1_D1    SDMMC1\nPC10   SDMMC1_D2    SDMMC1\nPC11   SDMMC1_D3    SDMMC1\ndefine FATFS_HAL_DEVICE SDCD1\ndefine HAL_OS_FATFS_IO 1\n\n# PWM/MOTORS (based on schematic)\nPE14 TIM1_CH4 TIM1 PWM(1) GPIO(50) \nPE13 TIM1_CH3 TIM1 PWM(2) GPIO(51) BIDIR\nPE11 TIM1_CH2 TIM1 PWM(3) GPIO(52) \nPA8  TIM1_CH1 TIM1 PWM(4) GPIO(53) BIDIR\nPA0  TIM2_CH1 TIM2 PWM(5) GPIO(54) BIDIR\nPB3  TIM2_CH2 TIM2 PWM(6) GPIO(55) \nPB10 TIM2_CH3 TIM2 PWM(7) GPIO(56) BIDIR \nPA3  TIM2_CH4 TIM2 PWM(8) GPIO(57) \nPB0  TIM3_CH3 TIM3 PWM(9) GPIO(58) BIDIR\n\n\n# SPI1 - IMU1\nPA5 SPI1_SCK SPI1\nPA6 SPI1_MISO SPI1\nPD7 SPI1_MOSI SPI1\nPA15 ICM_45686_1_CS CS\n# PA15 ICM_42688_1_CS CS\n\n# SPI4 for OSD\nPE2 SPI4_SCK SPI4\nPE5 SPI4_MISO SPI4\nPE6 SPI4_MOSI SPI4\nPE4 AT7456E_CS CS\n\n\n# I2C1 - external MAG/BARO\nI2C_ORDER I2C1\nPB8 I2C1_SCL I2C1 PULLUP\nPB9 I2C1_SDA I2C1 PULLUP\n\ndefine HAL_PROBE_EXTERNAL_I2C_COMPASSES 1\n# define AP_COMPASS_PROBING_ENABLED 1\ndefine HAL_I2C_INTERNAL_MASK 1\n\n# Barometer\nBARO BMP388 I2C:0:0x76\n\n# Builtin Compass (Define many type compass drivers)\ndefine AP_COMPASS_IIS2MDC_ENABLED 1\nCOMPASS IIS2MDC I2C:0:0x1E false ROTATION_YAW_270\nCOMPASS QMC5883L I2C:0:0x0d true ROTATION_NONE # GPS compass\nCOMPASS RM3100 I2C:0:0x20 true ROTATION_NONE \nCOMPASS RM3100 I2C:0:0x21 true ROTATION_NONE \nCOMPASS RM3100 I2C:0:0x22 true ROTATION_NONE \nCOMPASS RM3100 I2C:0:0x23 true ROTATION_NONE \n# define AP_COMPASS_BMM350_ENABLED 1\n# COMPASS BMM350  I2C:0:0x14 false ROTATION_PITCH_180 # BMM350, no OTP, ADSEL=LOW\n# COMPASS BMM350  I2C:0:0x15 false ROTATION_NONE # BMM350, no OTP, ADSEL=HIGH\n# COMPASS BMM350  I2C:0:0x16 false ROTATION_NONE # BMM350, have OTP, ADSEL=LOW\n# COMPASS BMM350  I2C:0:0x17 false ROTATION_NONE # BMM350, have OTP, ADSEL=HIGH\n\n# LED\n# LED1 HIGH, LED2 LOW, LED3 HIGH = 紅色\n# LED1 LOW, LED2 HIGH, LED3 HIGH = 綠色\n# LED1 表示紅色, LED2表示紅色, LED3表示藍色\nPD12 LED_RED       OUTPUT OPENDRAIN GPIO(89) LOW \nPD13 LED_BLUE      OUTPUT OPENDRAIN GPIO(90) LOW\nPD10 LED_GREEN     OUTPUT OPENDRAIN GPIO(91) LOW\n\n# 控制WS2812B LEDs\ndefine AP_NOTIFY_GPIO_LED_RGB_RED_PIN 89\ndefine AP_NOTIFY_GPIO_LED_RGB_BLUE_PIN 91\ndefine AP_NOTIFY_GPIO_LED_RGB_GREEN_PIN 90\ndefine AP_NOTIFY_GPIO_LED_RGB_ENABLED 1\n\n# Buzzer & Beeper\n# PD15 BUZZER OUTPUT GPIO(80) LOW\n# define HAL_BUZZER_PIN 80\nBEEPER_PIN PD15\n\n# CAN bus Define\nPD0 CAN1_RX CAN1\nPD1 CAN1_TX CAN1\nPD4 C1_SILENT OUTPUT LOW\n\n# Ethernet RMII\nPA1  ETH_RMII_REF_CLK    ETH1\nPA2  ETH_MDIO            ETH1\nPA7  ETH_RMII_CRS_DV     ETH1\nPC1  ETH_MDC             ETH1\nPC4  ETH_RMII_RXD0      ETH1\nPC5  ETH_RMII_RXD1      ETH1\nPB12 ETH_RMII_TXD0      ETH1\nPB13 ETH_RMII_TXD1      ETH1\nPB11 ETH_RMII_TX_EN     ETH1\ndefine BOARD_PHY_ID MII_LAN8720_ID\ndefine BOARD_PHY_RMII\ndefine AP_PERIPH_NETWORKING_ENABLED 1\n\nSPIDEV imu1      SPI1 DEVID1  ICM_45686_1_CS    MODE3  2*MHZ 16*MHZ\n# SPIDEV imu1      SPI1 DEVID1  ICM_42688_1_CS    MODE3  2*MHZ 16*MHZ\nSPIDEV osd       SPI4 DEVID1  AT7456E_CS        MODE0 10*MHZ 10*MHZ\n\nIMU Invensensev3 SPI:imu1 ROTATION_ROLL_180_YAW_90\n\ndefine HAL_BARO_ALLOW_INIT_NO_BARO\n\n\n"
